//
// Hanya 2, 26 dan 80 yang merupakan BLE advertising centers.
// ============================================================

const byte ble_channels[] = {
    1, 2, 3,
    25, 26, 27,
    79, 80, 81
};

const int BLE_CHANNELS_COUNT =
    sizeof(ble_channels) /
    sizeof(ble_channels[0]);


